package de.privacyguard.adhook;

import org.junit.Test;

import static org.junit.Assert.*;

public class HookTargetConfigParserTest {
    @Test
    public void acceptsValidTargetAndIgnoresDisplayMetadata() {
        HookTargetConfigParser.Result result = HookTargetConfigParser.parse(
                "# generated by FX\n" +
                "hook_ads_enabled=1\n" +
                "[list:hook_targets]\n" +
                "com.example.app,splash=1,feed=0,overlay=1,member_diag=1|LSPosed应用Hook|1\n");

        assertTrue(result.adsEnabled);
        assertEquals(1, result.targets.size());
        HookTargetConfigParser.Target target = result.targets.get("com.example.app");
        assertNotNull(target);
        assertTrue(target.splash);
        assertFalse(target.feed);
        assertTrue(target.overlay);
        assertTrue(target.memberDiag);
    }

    @Test
    public void membershipDiagnosticsRemainAvailableWhenAdMasterIsOff() {
        HookTargetConfigParser.Result result = HookTargetConfigParser.parse(
                "hook_ads_enabled=0\\n[list:hook_targets]\\n" +
                "com.example.app,splash=0,feed=0,overlay=0,member_diag=1\\n");
        assertFalse(result.isAdFilteringEnabledFor("com.example.app"));
        assertTrue(result.isMemberDiagnosticsEnabledFor("com.example.app"));
        assertTrue(result.isAnyFeatureEnabledFor("com.example.app"));
    }

    @Test
    public void adFeaturesStayDisabledWhenAdMasterIsOff() {
        HookTargetConfigParser.Result result = HookTargetConfigParser.parse(
                "hook_ads_enabled=0\\n[list:hook_targets]\\n" +
                "com.example.app,splash=1,feed=1,overlay=1,member_diag=0\\n");
        assertFalse(result.isAdFilteringEnabledFor("com.example.app"));
        assertFalse(result.isMemberDiagnosticsEnabledFor("com.example.app"));
        assertFalse(result.isAnyFeatureEnabledFor("com.example.app"));
    }
    @Test
    public void allowsDisabledMasterAndExplicitlyDisabledTarget() {
        HookTargetConfigParser.Result result = HookTargetConfigParser.parse(
                "hook_ads_enabled=0\n[list:hook_targets]\n" +
                "com.example.app,splash=0,feed=0,overlay=0,member_diag=0|Disabled|1\n");
        assertFalse(result.adsEnabled);
        assertFalse(result.targets.get("com.example.app").enabled());
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsMissingMasterSwitch() {
        HookTargetConfigParser.parse("[list:hook_targets]\ncom.example.app,splash=1\n");
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsMalformedRowInsteadOfPartiallyLoading() {
        HookTargetConfigParser.parse(
                "hook_ads_enabled=1\n[list:hook_targets]\n" +
                "com.example.good,splash=1,feed=0,overlay=0,member_diag=0\n" +
                "com.example.bad,splash=perhaps\n");
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsDuplicateTargetOptions() {
        HookTargetConfigParser.parse(
                "hook_ads_enabled=1\n[list:hook_targets]\n" +
                "com.example.app,splash=1,splash=0\n");
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsDuplicateTargetPackage() {
        HookTargetConfigParser.parse(
                "hook_ads_enabled=1\n[list:hook_targets]\n" +
                "com.example.app,splash=1\ncom.example.app,feed=1\n");
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsProtectedFrameworkPackages() {
        HookTargetConfigParser.parse(
                "hook_ads_enabled=1\n[list:hook_targets]\n" +
                "org.lsposed.manager,splash=1\n");
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsUnknownSectionsAndOptions() {
        HookTargetConfigParser.parse(
                "hook_ads_enabled=1\n[list:other]\ncom.example.app,splash=1\n");
    }

    @Test(expected = IllegalArgumentException.class)
    public void rejectsInvalidPackageNames() {
        HookTargetConfigParser.parse(
                "hook_ads_enabled=1\n[list:hook_targets]\n" +
                "not-a-package,splash=1\n");
    }
}
